diagrams.component:
@startuml
!theme plain
skinparam componentStyle rectangle
skinparam package {
  BackgroundColor #F8F9FA
  BorderColor #DEE2E6
}
title Architecture des modules

package "Modules" {
  [data] as data
  [backend] as backend
  [frontend] as frontend
  [constants] as frontend_constants
  [components] as frontend_components
  [] as _claude
}

package "API" {
  [routes] as backend_routes
}

package "Configuration" {
  [config] as backend_config
}

package "Services" {
  [services] as backend_services
  [services] as frontend_services
}

package "Utilitaires" {
  [utils] as frontend_utils
}


@enduml
